import pg from 'pg';
function stripSsl(url) { if (!url) return url; try { const u = new URL(url); ['sslmode','sslcert','sslkey','sslrootcert'].forEach(p=>u.searchParams.delete(p)); return u.toString(); } catch { return url; } }
const client = new pg.Client({ connectionString: stripSsl(process.env.DATABASE_URL), ssl: { rejectUnauthorized: false } });
await client.connect();

const colQ = `SELECT table_name, column_name FROM information_schema.columns WHERE (table_name='app_patients' AND column_name='race_color') OR (table_name='app_units' AND column_name='cnes') OR (table_name='app_users' AND column_name='cns') ORDER BY table_name, column_name`;
const cols = await client.query(colQ);
